mapper.select:
SELECT
FP.FINPROD_NAME assetName /*资产名称*/ ,FP.FINPROD_ID assetCode /*资产代码*/ ,'' assetTerm /*期次*/ ,'' vdate /*起息日*/ ,'' mdate /*到期日*/ ,'' assetAmt /*融资金额*/ ,'' assetRate /*到期收益率（%）*/ ,'02' hasChildren ,CONCAT(nvl(FP.FINPROD_ID,'null'),'') childInfo ,'root' parentInfo
'' assetName /*资产名称*/ ,'' assetCode /*资产代码*/ ,FPA.SALE_PERIOD assetTerm /*期次*/ ,TO_CHAR(FP.VDATE,'YYYY-MM-DD') vdate /*起息日*/ ,TO_CHAR(FP.MDATE,'YYYY-MM-DD') mdate /*到期日*/ ,(SELECT SUM(DECODE(A.PS,'T02',-1, 1)*A.PRIN_AMT) FROM TRD_PRODUCT_DEAL A WHERE A.FINPROD_ID = FP.FINPROD_ID AND A.IS_CANCEL = 'N' AND A.TRADE_STATUS !='03' AND A.SETTLE_DATE <= TO_DATE(#{qDate},'YYYY-MM-DD') ) assetAmt /*融资金额*/ ,ROUND(CCR.YIELD*100,4) assetRate /*到期收益率（%）*/ ,'01' hasChildren ,CONCAT(FP.FINPROD_ID,'_') childInfo ,CONCAT(nvl(FP.P_FINPROD_ID,'null'),'') parentInfo
FROM FIN_PRODUCT FP LEFT JOIN FIN_CASH_INFO CASH ON CASH.FINPROD_ID = FP.FINPROD_ID AND CASH.CASH_TYPE_1 = '02' AND CASH.CASH_TYPE_2 = 'C02' LEFT JOIN FIN_PRODUCT_ADD FPA ON FPA.FINPROD_ID = FP.FINPROD_ID LEFT JOIN FIN_CASH_CALC_RULE CCR ON CCR.CASH_ID = CASH.CASH_ID WHERE 1=1
AND FP.FINPROD_TYPE2 = #{FINPROD_TYPE2_F27}
AND FP.FINPROD_MARKET_ID = #{finprodMarketId}
AND EXISTS ( SELECT 1 FROM FIN_PRODUCT A WHERE A.P_FINPROD_ID = FP.FINPROD_ID
AND A.VDATE <= TO_DATE(#{qDate},'YYYY-MM-DD') AND A.MDATE >= TO_DATE(#{qDate},'YYYY-MM-DD')
)
AND FP.P_FINPROD_ID = #{parentId}
